from pathlib import Path
import re,hashlib
R=Path(__file__).resolve().parents[2];P=R/'public'
css='''.ax-twitch{background:#0e0e10;color:#efeff1;border:1px solid #36363b;border-radius:9px;overflow:hidden;font-family:Arial,sans-serif;margin-top:32px}.ax-twitch-top{height:54px;display:flex;align-items:center;gap:25px;padding:0 18px;background:#18181b;border-bottom:1px solid #303035;font-size:13px}.ax-twitch-logo{font-weight:900;font-size:25px;letter-spacing:-1.5px;color:#bf94ff}.ax-twitch-search{margin-left:auto;margin-right:auto;min-width:26%;padding:8px 12px;background:#303035;border:1px solid #55555a;border-radius:5px;color:#b6b6bf}.ax-twitch-dot{width:24px;height:24px;display:grid;place-items:center;border-radius:50%;background:#9146ff;font-size:10px}.ax-twitch-layout{display:grid;grid-template-columns:minmax(0,1fr) 220px}.ax-twitch-main{min-width:0}.ax-twitch-stage{aspect-ratio:16/9;position:relative;background:#08080b;overflow:hidden;display:flex;flex-direction:column;justify-content:space-between}.ax-twitch-stage::before{content:"";position:absolute;inset:0;background:radial-gradient(ellipse at 50% 25%,#292333 0%,#101014 52%,#08080b 90%);pointer-events:none}.ax-twitch-offline{z-index:1;padding:28px;display:flex;flex:1;flex-direction:column;justify-content:center;align-items:center;text-align:center}.ax-twitch-offline span{font-size:10px;letter-spacing:2px;color:#c8bbda;border:1px solid #6c6179;padding:6px 9px}.ax-twitch-offline strong{font-size:clamp(20px,3vw,46px);letter-spacing:-1.6px;line-height:1.05;margin-top:20px;font-weight:700}.ax-twitch-offline small{font-size:11px;color:#aaa4b2;margin-top:14px}.ax-twitch-banner{position:relative;z-index:1;background:#050507;min-height:0}.ax-twitch-banner video{display:block;width:100%;height:auto;aspect-ratio:16/3;object-fit:contain;background:#050507}.ax-twitch-channel{display:flex;gap:14px;align-items:center;padding:22px 20px}.ax-twitch-avatar{flex:0 0 42px;height:42px;background:#9146ff;border-radius:50%;display:grid;place-items:center;font-size:13px;font-weight:700}.ax-twitch-channel strong{font-size:16px}.ax-twitch-channel p{font-size:12px;color:#adadb8;margin:6px 0 0}.ax-twitch-channel em{font-style:normal;margin-left:auto;background:#303035;border:1px solid #55555a;padding:8px 12px;border-radius:4px;font-size:11px;color:#adadb8}.ax-twitch-tabs{display:flex;gap:24px;padding:0 20px 17px;font-size:12px;color:#adadb8}.ax-twitch-tabs b{color:#bf94ff;font-weight:400;border-bottom:2px solid #bf94ff;padding-bottom:10px}.ax-twitch-chat{border-left:1px solid #303035;display:flex;flex-direction:column;background:#18181b;font-size:12px;min-width:0}.ax-twitch-chat h3{font-size:11px;letter-spacing:.5px;text-align:center;padding:20px 10px;margin:0;border-bottom:1px solid #303035}.ax-twitch-chat p{font-size:11px;color:#adadb8;padding:16px;line-height:1.6;margin:0}.ax-twitch-chat .ax-twitch-chat-input{margin:auto 12px 16px;padding:12px;border:1px solid #55555a;border-radius:4px;font-size:10px;color:#adadb8}.ax-twitch-caption{font:10px/1.6 "IBM Plex Mono",monospace;margin:12px 0 0;text-transform:uppercase;color:#77716a}@media(max-width:800px){.ax-twitch-layout{grid-template-columns:1fr}.ax-twitch-chat{display:none}.ax-twitch-top{gap:18px;padding:0 12px}.ax-twitch-top .ax-twitch-search{display:none}.ax-twitch-dot{margin-left:auto}.ax-twitch-offline{padding:18px}.ax-twitch-offline strong{margin-top:12px}.ax-twitch-offline small{margin-top:8px}.ax-twitch-channel{padding:18px 14px}.ax-twitch-tabs{padding-left:14px}}@media(max-width:480px){.ax-twitch-stage{aspect-ratio:4/3}.ax-twitch-offline strong{font-size:26px}.ax-twitch-channel em{display:none}.ax-twitch-top{font-size:11px;gap:16px}.ax-twitch-channel strong{font-size:14px}}
'''
style='axion-twitch-'+hashlib.sha256(css.encode()).hexdigest()[:12]+'.css';(P/'assets'/style).write_text(css)
for it in [False,True]:
 T=lambda a,b:a if it else b;pre='it/' if it else '';p=P/(pre+'work/axion-controllers/index.html');s=p.read_text()
 # Move the actual website capture into the editorial digital chapter.
 photo=re.search(r'<figure class="ax-fig"><img src="/assets/axion-case/website-home-[^"]+".*?</figure>',s,re.S);assert photo
 capture=photo[0];s=s[:photo.start()]+s[photo.end():]
 title=T('STRUTTURA, IMMAGINI,<br>NAVIGAZIONE.','STRUCTURE, IMAGES,<br>NAVIGATION.')
 body=T('Ho curato il sito come punto di incontro tra identità visiva, fotografia e informazioni di prodotto. Il lavoro riguarda l’organizzazione delle pagine, le gerarchie dei contenuti e l’adattamento dei materiali ai formati digitali.','I worked on the website as the meeting point of visual identity, photography and product information. The work covers page structure, content hierarchy and the adaptation of materials to digital formats.')
 points=[(T('Gerarchia dei contenuti','Content hierarchy'),T('Titoli, descrizioni e immagini costruiscono diversi livelli di lettura, dalla vista d’insieme al dettaglio del prodotto.','Headings, descriptions and images create different reading levels, from an overview to product details.')),(T('Fotografia e interfaccia','Photography and interface'),T('Ho integrato le fotografie e il loro editing nel sito, mantenendo coerenza tra inquadrature, sfondi e palette dell’identità.','I integrated the photographs and their editing into the website, keeping framing, backgrounds and the identity palette consistent.'))]
 digital='<section class="ax-chapter"><span class="ax-label">04 / DIGITAL EXPERIENCE</span><h2>'+title+'</h2><p class="ax-body">'+body+'</p>'+capture+'<div class="ax-features">'+''.join('<article><h3>'+h+'</h3><p>'+t+'</p></article>' for h,t in points)+'</div></section>'
 s,n=re.subn(r'<section class="ax-chapter"><span class="ax-label">04 / DIGITAL EXPERIENCE</span>.*?</section>',lambda m:digital,s,flags=re.S);assert n==1
 # Remove these artworks as requested, not just their captions.
 s,n=re.subn(r'<div class="ax-pair ax-stack"><figure class="ax-fig"><img src="/assets/axion-communications/board-launch-.*?</figure><figure class="ax-fig"><img src="/assets/axion-communications/board-explained-.*?</figure></div>','',s,flags=re.S);assert n==1
 video=re.search(r'<figure class="ax-fig ax-player">(<video.*?</video>)<figcaption>TWITCH / ANIMATED BANNER</figcaption></figure>',s,re.S);assert video
 native=video[1]
 mock='<div class="ax-twitch" aria-label="'+T('Mockup di un canale Twitch con il banner animato originale Axion','Twitch channel mockup with the original Axion animated banner')+'"><div class="ax-twitch-top" aria-hidden="true"><span class="ax-twitch-logo">twitch</span><b>Following</b><b>Browse</b><span>•••</span><span class="ax-twitch-search">Search</span><span class="ax-twitch-dot">P</span></div><div class="ax-twitch-layout"><div class="ax-twitch-main"><div class="ax-twitch-stage"><div class="ax-twitch-offline" aria-hidden="true"><span>OFFLINE</span><strong>THE STREAM<br>WILL BE BACK SOON.</strong><small>PLAYER CHANNEL / AXION AFFILIATE</small></div><div class="ax-twitch-banner">'+native+'</div></div><div class="ax-twitch-channel" aria-hidden="true"><span class="ax-twitch-avatar">P</span><div><strong>Player channel</strong><p>Gaming · Axion affiliate</p></div><em>Notifications off</em></div><div class="ax-twitch-tabs" aria-hidden="true"><b>Home</b><span>About</span><span>Schedule</span><span>Videos</span></div></div><aside class="ax-twitch-chat" aria-hidden="true"><h3>STREAM CHAT</h3><p>Welcome to the chat room.</p><span class="ax-twitch-chat-input">Chat is offline</span></aside></div></div><p class="ax-twitch-caption">'+T('TWITCH / MOCKUP DI APPLICAZIONE — BANNER ORIGINALE, CANALE DIMOSTRATIVO.','TWITCH / APPLICATION MOCKUP — ORIGINAL BANNER, DEMONSTRATION CHANNEL.')+'</p>'
 s=s[:video.start()]+mock+s[video.end():]
 s=s.replace('</head>',f'<link rel="stylesheet" href="/assets/{style}"></head>')
 s=s.replace('il sito e il percorso di configurazione, l’identità visiva','il sito, l’identità visiva').replace('the website and configuration journey, visual identity','the website, visual identity')
 p.write_text(s)
print(style)
